            continue
        path = os.path.join(dirpath, f)
        if "/src/" not in path and not path.endswith("/src"):
            # packages/x/src/...
            if not re.search(r'/src/', path):
                continue
        text = open(path, encoding="utf-8", errors="replace").read()
        lines = text.splitlines()
        use_idxs = [i for i,l in enumerate(lines) if re.match(r'^use ', l)]
        if len(use_idxs) >= 2:
            gap = []
            for i in range(use_idxs[0], use_idxs[-1]):
                l = lines[i]
                if re.match(r'^use ', l) or l.strip()=='' or l.strip().startswith('//'):
