import json, subprocess
from collections import Counter
old = json.loads(subprocess.check_output(['git','show','58cfcac1395c66ae96fa88d204a3a84cab18e27d:tests/Repo/Arch/Fixtures/target-map.json']))
new = json.loads(open('tests/Repo/Arch/Fixtures/target-map.json').read())
o = {t['fqcn']: t for t in old['types']}
n = {t['fqcn']: t for t in new['types']}
surf_diff = []
for fq, t in o.items():
    if t.get('surface') != n[fq].get('surface'):
        surf_diff.append((fq, t.get('surface'), n[fq].get('surface'), t.get('kind')))
print('surface diffs', len(surf_diff))
for row in surf_diff:
    print(' DIFF', *row)
# undecided old
und = [fq for fq,t in o.items() if t.get('surface')=='undecided']
print('old undecided', len(und))
for fq in und:
    print('  ', fq, '->', n[fq]['surface'], 'kind', o[fq].get('kind'), 'note', (o[fq].get('note') or '')[:140])
# Spi:Call
print('--- Spi:Call old vs new ---')
for fq,t in sorted(o.items()):
    if t.get('surface')=='Spi:Call' or n[fq].get('surface')=='Spi:Call':
        if t.get('surface')!=n[fq].get('surface') or t.get('surface')=='Spi:Call':
            print(fq, t.get('surface'), '->', n[fq].get('surface'), t.get('kind'))
print('new Spi:Call', sum(1 for t in n.values() if t.get('surface')=='Spi:Call'))
# enums traits interfaces surface distribution
for kind in ['enum','trait','interface','class']:
    c = Counter(t.get('surface') for t in n.values() if t.get('kind')==kind)
    print(kind, dict(c))
# needs note: old notes containing ?
notes = [(fq, t.get('surface'), (t.get('note') or '')[:160]) for fq,t in o.items() if t.get('note')]
print('old with note', len(notes))
# print notes that mention surface or undecided or needs
for fq,s,note in notes:
    low = note.lower()
    if 'surface' in low or 'undecided' in low or 'api' in low or 'spi' in low or 'internal' in low:
        print('NOTE', fq, s, '->', n[fq]['surface'], '|', note[:180])
